<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import http from'../api/http';import{useAuthStore}from'../stores/auth'
const auth=useAuthStore(),rows=ref<any[]>([]),total=ref(0),loading=ref(false),dialog=ref(false),slots=ref<any[]>([]),schedule=ref<any>(null),submitting=ref(false);const query=reactive({page:1,page_size:10,status:''});const booking=reactive({slot_id:undefined as number|undefined,reason:''})
const title=computed(()=>auth.user?.role==='doctor'?'接诊管理':auth.user?.role==='patient'?'我的预约':'预约管理')
async function load(){loading.value=true;try{const{data}=await http.get('/appointments',{params:query});rows.value=data.results;total.value=data.count}finally{loading.value=false}}
async function openBooking(){const raw=sessionStorage.getItem('selected_schedule');if(!raw){ElMessage.info('请先在“就诊预约”中选择排班');location.assign('/schedules');return}schedule.value=JSON.parse(raw);dialog.value=true;booking.slot_id=undefined;booking.reason='';slots.value=(await http.get(`/schedules/${schedule.value.id}/slots`)).data}
async function submit(){if(!booking.slot_id||booking.reason.trim().length<2)return ElMessage.warning('请选择号源并填写就诊原因');await ElMessageBox.confirm('确认提交本次预约吗？','预约确认',{type:'info'});submitting.value=true;try{await http.post('/appointments',booking);ElMessage.success('预约成功');dialog.value=false;sessionStorage.removeItem('selected_schedule');load()}finally{submitting.value=false}}
async function action(row:any,status:string){await ElMessageBox.confirm('确认执行此操作吗？','操作确认',{type:'warning'});await http.patch(`/appointments/${row.id}/status`,{status});ElMessage.success('状态更新成功');load()}
onMounted(()=>{load();if(auth.user?.role==='patient'&&sessionStorage.getItem('selected_schedule'))openBooking()})
</script>
<template><div><div class="page-title"><div><h1>{{title}}</h1><p>按状态查看预约，并完成取消、接诊和诊疗流程</p></div><el-button v-if="auth.user?.role==='patient'" type="primary" @click="openBooking">新建预约</el-button></div><el-card><div class="toolbar"><el-select v-model="query.status" clearable placeholder="全部状态" @change="query.page=1;load()"><el-option v-for="x in [['pending','待就诊'],['in_progress','就诊中'],['completed','已完成'],['cancelled','已取消'],['no_show','爽约']]" :key="x[0]" :label="x[1]" :value="x[0]"/></el-select></div><el-table v-loading="loading" :data="rows"><el-table-column prop="appointment_no" label="预约编号" min-width="150"/><el-table-column prop="visit_date" label="就诊日期"/><el-table-column prop="department_name" label="科室"/><el-table-column prop="doctor_name" label="医师"/><el-table-column prop="patient_name" label="患者"/><el-table-column label="时间"><template #default="{row}">{{row.start_time.slice(0,5)}}–{{row.end_time.slice(0,5)}}</template></el-table-column><el-table-column prop="reason" label="就诊原因" min-width="180"/><el-table-column label="状态"><template #default="{row}"><el-tag>{{row.status_label}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="160"><template #default="{row}"><el-button v-if="auth.user?.role==='patient'&&row.status==='pending'" link type="danger" @click="action(row,'cancelled')">取消</el-button><template v-if="auth.user?.role==='doctor'"><el-button v-if="row.status==='pending'" link type="primary" @click="action(row,'in_progress')">开始接诊</el-button><el-button v-if="row.status==='in_progress'" link type="success" @click="action(row,'completed')">完成诊疗</el-button></template></template></el-table-column></el-table><div class="pagination"><span>共 {{total}} 条</span><el-pagination v-model:current-page="query.page" v-model:page-size="query.page_size" layout="sizes,prev,pager,next" :total="total" @change="load"/></div></el-card><el-dialog v-model="dialog" title="预约挂号" width="560px"><div v-if="schedule" class="summary"><b>{{schedule.department_name}} · {{schedule.doctor_name}}</b><p>{{schedule.schedule_date}} {{schedule.start_time.slice(0,5)}}–{{schedule.end_time.slice(0,5)}}</p></div><el-form label-position="top"><el-form-item label="预约号源" required><div class="slots"><el-button v-for="x in slots" :key="x.id" :type="booking.slot_id===x.id?'primary':'default'" @click="booking.slot_id=x.id">{{x.start_time.slice(0,5)}}–{{x.end_time.slice(0,5)}}</el-button></div><el-empty v-if="!slots.length" :image-size="60" description="暂无可预约号源"/></el-form-item><el-form-item label="就诊原因" required><el-input v-model="booking.reason" type="textarea" :rows="3" maxlength="300" show-word-limit/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="submitting" @click="submit">确认预约</el-button></template></el-dialog></div></template>
